import 'package:dio/dio.dart';import 'package:flutter/foundation.dart';abstract class Failure {  final String errMessage;  const Failure(this.errMessage);}class ServerFailure extends Failure {  ServerFailure(super.errMessage);  factory ServerFailure.unauthorized() {    return ServerFailure("🔐 Unauthorized access. Please login again.");  }  factory ServerFailure.fromDioError(DioException dioError) {    return ServerFailure(ApiErrorHandler.getErrorMessage(dioError));  }  factory ServerFailure.fromResponse(int? statusCode, dynamic response) {    return ServerFailure(ApiErrorHandler.getMessageFromResponse(response));  }}class ApiErrorHandler {  // Main function to get error message from any error  static String getErrorMessage(dynamic error) {    if (error is DioException) {      // Connection and network errors      if (error.type == DioExceptionType.connectionTimeout ||          error.type == DioExceptionType.sendTimeout ||          error.type == DioExceptionType.receiveTimeout) {        return "Network timeout, please try again";      }      // Handle API response with error      if (error.type == DioExceptionType.badResponse) {        return getMessageFromResponse(error.response?.data);      }      // No internet      if (error.type == DioExceptionType.connectionError) {        return "No internet connection, please check your network";      }      // Other Dio errors      return "Unexpected error occurred, please try again";    } else {      return "Unexpected error: ${error.toString()}";    }  }  // Function to extract message from API response  static String getMessageFromResponse(dynamic response) {    // Default message if we can't find anything in the response    String message = "An unexpected error occurred";    if (response is Map<String, dynamic>) {      // Check for message field first (most common)      if (response.containsKey('message') && response['message'] != null) {        if (response['message'] is String) {          return response['message'];        }      }      // Check for error field      if (response.containsKey('error') && response['error'] != null) {        if (response['error'] is String) {          return response['error'];        }      }      // Check for errors object that might contain messages      if (response.containsKey('errors') && response['errors'] != null) {        final errors = response['errors'];        if (errors is Map<String, dynamic>) {          // Get the first error message from the map          final firstErrorKey = errors.keys.first;          final errorValue = errors[firstErrorKey];          if (errorValue is List && errorValue.isNotEmpty) {            return errorValue.first.toString();          } else if (errorValue != null) {            return errorValue.toString();          }        } else if (errors is List && errors.isNotEmpty) {          return errors.first.toString();        }      }    } else if (response is String) {      // If the response is directly a string      return response;    }    if (kDebugMode) {      print("❌ API Error: $message");    }    return message;  }}